      borderColor: invalid ? "var(--danger)" : s.focus ? "var(--border-interactive)" : "transparent",
      background: disabled ? "var(--surface-sunken)" : "var(--surface-raised)",
      boxShadow: s.hover && !s.focus ? "var(--shadow-md)" : "var(--shadow-sm)",
